        children = {}
        for i in range(n):
            parts = lines[idx].split()
            idx += 1
            if parts[0] == '-1':
                children[i] = (int(parts[1]), int(parts[2]))
            else:
                leafs[i] = int(parts[0])

        # Compute leaf counts for subtree
        def num_leaves(u):
            if u in leafs:
                return 1
            else:
                l, r = children[u]
                return num_leaves(l) + num_leaves(r)

        memo = {}

        def compute(u):
            if u in memo:
                return memo[u]

            if u in leafs:
                res = leafs[u]
            else:
                l, r = children[u]
                v_left = compute(l)
                v_right = compute(r)
                ops_before = (num_leaves(l) - 1) + (num_leaves(r) - 1)
                player = 0 if (ops_before % 2 == 0) else 1

                if player == 0:  # Pieguy's turn, maximize
                    res = max(v_left, v_right)
                else:  # Piegirl's turn, minimize
                    res = min(v_left, v_right)

            memo[u] = res
            return res

        results.append(str(compute(0)))

    return '\n'.join(results)
