        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + s1[i-1]
                else:
                    if len(dp[i-1][j]) > len(dp[i][j-1]):
                        dp[i][j] = dp[i-1][j]
                    else:
                        dp[i][j] = dp[i][j-1]
        return dp[n][m] if dp[n][m] else '0'

    # KMP prefix function
    pi = [0] * v_len
    k = 0
    for q in range(1, v_len):
        while k > 0 and virus[k] != virus[q]:
            k = pi[k-1]
        if virus[k] == virus[q]:
