# solution.py

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "-1\n"

    # Union-Find to find connected components
    parent = list(range(n + 1))
    sz = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            root = x
            while parent[root] != root:
                root = parent[root]
            curr = x
            while curr != root:
                nxt = parent[curr]
                parent[curr] = root
                curr = nxt
            return root
        return x

    def union(x, y):
        px = find(x)
        py = find(y)
        if px != py:
            if sz[px] < sz[py]:
                px, py = py, px
            parent[py] = px
            sz[px] += sz[py]
            return 1
        return 0

    # Process all edges
    for i in range(1, min(len(lines), m + 1)):
        if lines[i].strip():
            try:
                u, v = map(int, lines[i].split())
                union(u, v)
            except:
                pass

    # Collect component sizes
    comp_sizes = []
    for i in range(1, n + 1):
        if parent[i] == i:
            comp_sizes.append(sz[i])

    if not comp_sizes:
        return "-1\n"

    # Generate lucky numbers up to the total sum
    total = sum(comp_sizes)
    lucky = set()
    q = [4, 7]
    while q:
        num = q.pop(0)
        if num <= total:
            lucky.add(num)
        else:
            continue
        q.append(num * 10 + 4)
        q.append(num * 10 + 7)

    if not lucky:
        return "-1\n"

    lucky_nums = sorted(lucky)

    # DP: dp[s] = minimum number of components needed to reach sum s
    dp = {0: 0}

    for s in comp_sizes:
        new_sums = {}
        for prev_sum, count in dp.items():
            new_sum = prev_sum + s
            if new_sum not in dp or dp[new_sum] > count + 1:
                dp[new_sum] = min(dp.get(new_sum, float('inf')), count + 1)
                if new_sum in lucky_nums:
                    min_roads = min(min_roads, count + 1)

        # Check if already lucky
        for prev_sum, count in dp.items():
            if prev_sum in lucky_nums:
                min_roads = min(min_roads, count)

    # Final check
    min_roads = float('inf')
    for l in lucky_nums:
        if l in dp:
            min_roads = min(min_roads, dp[l])

    if min_roads == float('inf'):
        return "-1\n"
    else:
        return f"{min_roads - 1}\n"
