from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        edges.append((u, v))

    if m % 2 != 0:
        return "No solution\n"

    adj = defaultdict(list)
    for idx, (u, v) in enumerate(edges):
        adj[u].append((v, idx))
        adj[v].append((u, idx))

    used = [False] * m
    result = []

    def pair_edges(u):
        neighbors = adj[u]
        n_neigh = len(neighbors)
        if n_neigh % 2 == 1:
            # Degree is odd, pair as many as possible
            n_neigh = n_neigh - 1
            for i in range(0, n_neigh, 2):
                v1, idx1 = neighbors[i]
                v2, idx2 = neighbors[i + 1]
                if not used[idx1] and not used[idx2]:
                    result.append(f"{v1} {u} {v2}")
                    used[idx1] = True
                    used[idx2] = True
            return

        # Even degree - all possible pairings
        for i in range(0, n_neigh, 2):
            v1, idx1 = neighbors[i]
            v2, idx2 = neighbors[i + 1]
            if not used[idx1] and not used[idx2]:
                result.append(f"{v1} {u} {v2}")
                used[idx1] = True
                used[idx2] = True

    def dfs(u, _):
        for v, idx in adj[u]:
            if not used[idx]:
                used[idx] = True
                dfs(v, idx)

    # Greedy DFS
    for i in range(1, n + 1):
        if not any(not used[idx] for idx in range(m)):
            break
        dfs(i, None)

    kon = []
    print('\n'.join(kon))
