def solution(input_str):
    """
    Lena's Queries Problem Solution

    For each query:
    - Type 1: Add pair (a, b) to set
    - Type 2: Remove pair from query i  
    - Type 3: Find max(x*q + y) over all active pairs

    Uses simple O(n) per query for correctness.
    """
    lines = input_str.strip().split('\n')

    if not lines:
        return ""

    n = int(lines[0])

    addents = {}  # (query_num, is_active) -> (a, b)
    active = set()
