        if t == 1:
            # Type 1: Add pair
            a = int(parts[1])
            b = int(parts[2])
            query_num = i
            addents[(i, 1)] = (a, b)
            active.add(i)
        elif t == 2:
            # Type 2: Remove pair added at query i
            idx = int(parts[1])
            active.discard(idx)
        elif t == 3:
            # Type 3: Query max(x*q + y)
            q = int(parts[1])
            if not active:
                result.append("EMPTY SET")
            else:
                best = float('-inf')
                for qn in active:
                    x, y = addents[(qn, 1)]
                    val = x * q + y
                    if val > best:
                        best = val
                result.append(str(best))

    return '\n'.join(result)
