def solution(input_str):
    n, m = map(int, input_str.strip().split())

    # Four T-shape orientations
    shapes = [
        [(0,0), (0,1), (0,2), (1,1)],  # Top (horizontal bar on top)
        [(0,2), (1,1), (2,2), (1,0)],  # Bottom  
        [(0,1), (1,0), (1,1), (2,1)],  # Left
        [(0,1), (1,1), (2,1), (1,2)],  # Right
    ]

    grid = [['.' for _ in range(m)] for _ in range(n)]
    best_count = [0]
    best_solution = [row[:] for row in grid]

    def can_place(r, c, shape):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= n or nc < 0 or nc >= m or grid[nr][nc] != '.':
                return False
        return True

    def place(r, c, shape):
        for dr, dc in shape:
            grid[r+dr][c+dc] = letters[next(i for i, (home_r, home_c) in enumerate(occupied) if (home_r, home_c) == (r,c))]

    letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    occupied = set()
    piece_num = [0]

    def backtrack(count):
        if count > best_count[0]:
            best_count[0] = count
            import copy
            best_solution = [row[:] for row in grid]

        # Find next empty cell
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    for shape in shapes:
                        if can_place(r, c, shape):
                            # Place piece
                            for dr, dc in shape:
                                grid[r+dr][c+dc] = letters[piece_num[0]]
                            piece_num[0] += 1
                            occupied.add((r,c))

                            # Place all cells
                            occupied_cells = set()
                            for dr, dc in shape:
                                grid[r+dr][c+dc] = letters[piece_num[0]]
                                occupied.add((r+dr, c+dc))

                            backtrack(count + 1)

                            # Remove
                            for dr, dc in shape:
                                grid[r+dr][c+dc] = '.'
                            for (rr, cc) in occupied:
                                occupied.remove((rr, cc))
                            piece_num[0] -= 1

    backtrack(0)

    result = f"{best_count[0]}\n"
    for row in best_solution:
        result += "".join(row) + "\n"

    return result.strip() + "\n"
