    def remove(r, c, shape):
        for dr, dc in shape:
            grid[r+dr][c+dc] = '.'

    letter = [65]  # ASCII 'A'

    def backtrack():
        # Update best if we have more pieces
        placed = -1
        for r in range(n):
            for c in range(m):
                if grid[r][c] != '.':
                    placed += 1
        if placed >= best_count[0]:
            best_count[0] = placed + 1 if placed >= best_count[0] else best_count[0]
            best_solution = [row[:] for row in grid]

        # Try to place from first empty cell
        r, c = 0, 0
        found = False
        while r < n and c < m:
            if grid[r][c] == '.':
                found = True
                break
            r += 1
            c = 0 if c + 1 == m else c + 1

        if not found:
            return

        for i, shape in enumerate(shapes):
            if can_place(r, c, shape):
                place(rt, c, shape, chr(letter[0]))
                letter[0] += 1
                backtrack()
                letter[0] -= 1
                remove(r, c, shape)
                break

    backtrack()

    result = f"{best_count[0]}\n"
    for row in best_solution:
        result += "".join(row) + "\n"
    return result
