```python
def solution(input_str):
    n, m = map(int, input_str.strip().split())

    shapes = [
        [(0,0), (0,1), (0,2), (1,1)],
        [(0,2), (1,1), (2,2), (1,0)],
        [(0,1), (1,0), (1,1), (2,1)],
        [(0,1), (1,1), (2,1), (1,2)],
    ]

    grid = [['.' for _ in range(m)] for _ in range(n)]
    best_count = [0]

    def count_pieces():
        return sum(1 for r in range(n) for c in range(m) if grid[r][c] != '.') // 4

    def backtrack():
        c = count_pieces()
        if c > best_count[0]:
            best_count[0] = c
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    return
                for i, shape in enumerate(shapes):
                    if can_place(r, c, shape):
                        for dr, dc in shape:
                            grid[r+dr][c+dc] = grid[r+dr][c+dc] if grid[r+dr][c+dc] != '.' else '#'
                        backtrack()
                        for dr, dc in shape:
                            grid[r+dr][c+dc] = '.'
                        break

    result = f"{best_count[0]}\n" + "\n".join("".join(row) for row in best_solution) + "\n"
    return result
