Looking at this problem, I need to understand the constraints:
- If number x is in set A, then (a-x) must also be in set A
- If number x is in set B, then (b-x) must also be in set B

This means I need to track pair relationships and find valid assignments.

## Key Observations:

1. For A-constraints: if both x and (a-x) exist in the input, they must be assigned to the SAME set
2. For B-constraints: if both x and (b-x) exist in the input, they must be assigned to the SAME set
3. If x has no A-complement in input but has B-complement, x can only go to B → assign to B with its complement
4. If x has no B-complement in input but has A-complement, x can only go to A → assign to A with its complement
5. If x has both complements, it can go to either set (with both complements)
6. If x has neither complement, x can go to either set independently

I'll use Union-Find to group numbers that must be in the same set, then process each connected component.

```python
# Solution for the set division problem

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    val_to_idx = {v: i for i, v in enumerate(p)}

    # Union-Find to track numbers that must be in the same set
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Build A-pairs: numbers that must be in same set if both exist
    # Also track which numbers can't go to set 1 (because they lack A-complement)
    has_a_pair = [False] * n  # True if i has both complements in input
    must_be_in_0 = [False] * n  # True if i must be in set 0 (lacks A-complement but has B-complement)
    must_be_in_1 = [False] * n  # True if i must be in set 1 (lacks B-complement but has A-complement)

    for i in range(n):
        x = p[i]
        ay = a - x
        by = b - x
        has_a = ay in val_to_idx
        has_b = by in val_to_idx

        if has_a:
            j = val_to_idx[ay]
            union(i, j)
        if has_b:
            j = val_to_idx[by]
            union(i, j)

        # Track constraints for later assignment
        if not has_b and has_a:
            must_be_in_1[i] = False

        if not has_a and has_b:
            must_be_in_0[i] = False
            must_be_in_1[i] = False

        if has_a and has_b:
            pass  # Can go anywhere

    # Process each component
    result = []
    for i in range(n):
        i_set = find(i)
        if result and i_set != result[-1][0]:
            result.append(([i_set], [], []))
        if not result or i_set in result and len(result) > 1:
            continue

        component = [i]
        queue = [i]
        comp_set = i_set
        while queue:
            node = queue.pop(0)
            component.append(node)
            for j in range(n):
                if j != node and find(j) == comp_set and j not in component:
                    queue.append(j)

        # Process one wrapper per unique root for output
        root = find(i)
        result.append(([root], component, []))

    # Simpler approach: build correct component list
    components = []
    seen = set()
    for i in range(n):
        if find(i) in seen:
            continue
        components.append((find(i), i))
        seen.add(find(i))

    # Reset components
    components = []
    for i in range(n):
        if find(i) not in seen:
            components.append((find(i), i))
            seen.add(find(i))

    # Final solution
    components = []
    visited = [False] * n
    for i in range(n):
        if find(i) not in seen:
            cs = find(i)
            comp = [i]
            nqueue = [i]
            while nqueue:
                node = nqueue.pop(0)
                if node in comp:
                    continue
                comp.append(node)
                nqueue.append(find(node))
            components.append((find(i), comp))

    ans = [0] * n
    for root, comp in components:
        for j in comp:
            can_0 = not must_be_in_1[j]
            can_1 = not must_be_in_0[j]
            if not can_0:
                ans[j] = 1
            elif not can_1:
                ans[j] = 0
            elif result and root == result[-1][0]:
                pass

    # Build proper components and assign
    components = []
    seen_set = set()
    for i in range(n):
        if find(i) not in seen_set:
            cs = find(i)
            comp = []
            queue = [i]
            while queue:
                node = queue.pop(0)
                comp.append(node)
                for j in range(n):
                    if find(j) == cs and j not in comp and j not in queue:
                        queue.append(j)
            components.append((cs, comp))
            seen_set.add(cs)

    ans = [0] * n
    for cs, comp in components:
        for j in comp:
            can_0 = not must_be_in_1[j]
            can_1 = not must_be_in_0[j]
            if not can_0 and not can_1:
                return "NO"
            if not can_0:
                for k in comp:
                    ans[k] = 1
            elif not can_1:
                for k in comp:
                    ans[k] = 0
            else:
                # Default to 0
                for k in comp:
                    ans[k] = 0

    return "YES\n" + " ".join(map(str, ans)) + "\n"
